import{Ct as e,at as t,it as n,st as r,t as i,yt as a}from"./chunks/framework.DJ1YMEMN.js";var o=JSON.parse(`{"title":"@warp-drive/alien-signals/primitives","description":"Signals, memos and a watcher, built on alien-signals, that back WarpDrive reactivity and let framework integrations observe it.","frontmatter":{"title":"@warp-drive/alien-signals/primitives","description":"Signals, memos and a watcher, built on alien-signals, that back WarpDrive reactivity and let framework integrations observe it.","outline":{"level":[2,3]}},"headers":[],"relativePath":"api/@warp-drive/alien-signals/primitives/index.md","filePath":"api/@warp-drive/alien-signals/primitives/index.md"}`),s={name:`api/@warp-drive/alien-signals/primitives/index.md`};function c(i,o,s,c,l,u){let d=e(`ModuleBadge`);return a(),n(`div`,null,[r(d,{path:`@warp-drive/alien-signals/primitives`}),o[0]||=t(`<p>The reactive primitives behind <code>@warp-drive/alien-signals</code>: a small signals graph built on the push-pull algorithm from <a href="https://github.com/stackblitz/alien-signals" target="_blank" rel="noreferrer">alien-signals</a>.</p><p>Most apps only need the <a href="/pr-preview/pr-11389/api/@warp-drive/alien-signals/install/"><code>install</code></a> entry point. Import from this module when you are building a framework integration that needs to observe <strong><em>Warp</em>Drive</strong>&#39;s signals, the way <code>@warp-drive/react</code> does for its <code>ReactiveContext</code>:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Watcher, createSignal, consumeSignal, notifySignal } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/alien-signals/primitives&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The graph implements only what <strong><em>Warp</em>Drive</strong>&#39;s <a href="./../../core/configure/types/SignalHooks">SignalHooks</a> need, not the TC39 Signals API:</p><ul><li>a <a href="./types/SignalNode">SignalNode</a> holds no value. It is a &quot;side signal&quot; that tells consumers the value it guards has changed, so every <a href="./functions/notifySignal">notifySignal</a> counts as a change.</li><li>a <a href="./types/MemoNode">MemoNode</a> caches the result of a function, including a thrown error, until a signal or memo it read changes.</li><li>a <a href="./classes/Watcher">Watcher</a> is told, once, when anything it watches may have changed.</li></ul><p>A memo that nothing subscribes to (no watcher, and no other memo that reads it) releases its links to the signals it read in a microtask after it is read, so a long-lived signal never keeps a short-lived memo, or the object that owns it, alive. Its next read recomputes it.</p><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to “Classes”">​</a></h2><ul><li><a href="./classes/Watcher">Watcher</a></li></ul><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><a href="./functions/consumeSignal">consumeSignal</a></li><li><a href="./functions/createMemo">createMemo</a></li><li><a href="./functions/createSignal">createSignal</a></li><li><a href="./functions/hasSubscribers">hasSubscribers</a></li><li><a href="./functions/isTracking">isTracking</a></li><li><a href="./functions/notifySignal">notifySignal</a></li><li><a href="./functions/readMemo">readMemo</a></li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h2><ul><li><a href="./types/MemoNode">MemoNode</a></li><li><a href="./types/SignalNode">SignalNode</a></li></ul>`,12)])}var l=i(s,[[`render`,c]]);export{o as __pageData,l as default};